<?php if(isset($counts)): ?><section class="kpi-grid"><article class="panel kpi-card">DRAFT: <?= (int)($counts["DRAFT"]??0) ?></article><article class="panel kpi-card">Dalam Perjalanan: <?= (int)($counts["SENT"]??0) ?></article><article class="panel kpi-card">RECEIVED: <?= (int)($counts["RECEIVED"]??0) ?></article><article class="panel kpi-card">CANCELLED: <?= (int)($counts["CANCELLED"]??0) ?></article></section><form class="panel" method="get"><label>Status<select name="status"><option value="">Semua status</option><option value="DRAFT">DRAFT</option><option value="SENT">Dalam Perjalanan</option><option value="RECEIVED">RECEIVED</option><option value="CANCELLED">CANCELLED</option></select></label><button class="button">Filter</button></form><?php endif ?><?php use Hls\Http\View as V; ?><?php if($access->can('inventory.transfer.create')): ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Nomor transfer<input name="transfer_ref" required></label><label>Tanggal<input type="date" name="transfer_date" value="<?= date('Y-m-d') ?>" required></label><label>Cabang asal<select name="source_branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code']) ?></option><?php endif; endforeach ?></select></label><label>Gudang asal<select name="source_warehouse_id" required><?php foreach($warehouses as $w): if($access->branch((int)$w['branch_id'])): ?><option value="<?= (int)$w['id'] ?>"><?= V::escape($w['code']) ?></option><?php endif; endforeach ?></select></label><label>Cabang tujuan<select name="destination_branch_id" required><?php foreach($branches as $b): if($access->branch((int)$b['id'])): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['code']) ?></option><?php endif; endforeach ?></select></label><label>Gudang tujuan<select name="destination_warehouse_id" required><?php foreach($warehouses as $w): if($access->branch((int)$w['branch_id'])): ?><option value="<?= (int)$w['id'] ?>"><?= V::escape($w['code']) ?></option><?php endif; endforeach ?></select></label><label>Keterangan<textarea name="note"></textarea></label><div><select name="item_id[]" required><option value="">Pilih barang</option><?php foreach($items as $i): ?><option value="<?= (int)$i['id'] ?>"><?= V::escape($i['code'].' - '.$i['name']) ?></option><?php endforeach ?></select><input name="quantity[]" type="number" min="0.001" step="0.001" required></div><button class="button button-primary">Simpan Draft</button></form></section><?php endif ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Asal</th><th>Tujuan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['transfer_ref']) ?></td><td><?= V::escape($r['transfer_date']) ?></td><td><?= V::escape($r['source_branch'].' / '.$r['source_warehouse']) ?></td><td><?= V::escape($r['destination_branch'].' / '.$r['destination_warehouse']) ?></td><td><?= V::escape($r['status']) ?></td><td><?php if($r['status']==='DRAFT'&&$access->can('inventory.transfer.send')): ?><form method="post" action="<?= $this->url('/inventory/transfer-send') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="button">Kirim</button></form><?php elseif($r['status']==='SENT'&&$access->can('inventory.transfer.receive')): ?><form method="post" action="<?= $this->url('/inventory/transfer-receive') ?>"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="button">Terima</button></form><?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-state">Belum ada transfer gudang.</td></tr><?php endif ?></tbody></table></div></section>

